// Derived collections — built once at module load (cold requires are ms).
export const NSE_SYMBOL_SET: ReadonlySet<string> = new Set(NSE_SCRIPS.map((s) => s.symbol));
export const NSE_SCRIP_BY_SYMBOL: Readonly<Record<string, NseScrip>> = Object.freeze(
  Object.fromEntries(NSE_SCRIPS.map((s) => [s.symbol, s])),
);

/** O(1) membership — is this an NSE-listed Equity-series symbol? */
export function isNseSymbol(symbol: string): boolean {
  return NSE_SYMBOL_SET.has(symbol.toUpperCase().trim());
}

/** Metadata lookup by exact symbol (case-insensitive). */
export function getNseScrip(symbol: string): NseScrip | undefined {
  return NSE_SCRIP_BY_SYMBOL[symbol.toUpperCase().trim()];
}

/** Case-insensitive search — SYMBOL prefix (priority), then symbol/company substring. */
export function searchNseSymbols(query: string, limit = 10): NseScrip[] {
  const q = query.toUpperCase().trim();
  if (!q) return [];
  const exact: NseScrip[] = [];
  const rest: NseScrip[] = [];
  for (const s of NSE_SCRIPS) {
    const sym = s.symbol.toUpperCase();
    if (sym.startsWith(q)) exact.push(s);
    else if (sym.includes(q) || s.companyName.toUpperCase().includes(q)) rest.push(s);
    if (exact.length + rest.length >= limit * 4) break;
  }
  return [...exact, ...rest].slice(0, limit);
}
